export enum OfferingVisibility {
    private = 'private',
    public = 'public',
}

export enum ValidBillingCycles {
    monthly = 'monthly',
    'annualToDate' = 'annualToDate',
    topUp = 'topUp',
}

@ValidatorConstraint({ name: 'TopUpBillingCycleRule', async: false })
export class TopUpBillingCycleRule implements ValidatorConstraintInterface {
    validate(_value: unknown, args: ValidationArguments) {
        const obj = args.object as CreateOfferingDTO;
        const isTopUp = obj.billingCycle === ValidBillingCycles.topUp;
        const hasTopUpAmount = obj.topUpAmount !== undefined && obj.topUpAmount !== null && obj.topUpAmount !== '';
        const hasTopUpThreshold =
            obj.topUpThreshold !== undefined && obj.topUpThreshold !== null && obj.topUpThreshold !== '';

        if (obj.offeringType === OfferingType.subscription && isTopUp) {
            return false;
        }
        if (isTopUp && !hasTopUpAmount) {
            return false;
        }
        if (!isTopUp && (hasTopUpAmount || hasTopUpThreshold)) {
            return false;
        }
        return true;
    }

    defaultMessage(args: ValidationArguments) {
        const obj = args.object as CreateOfferingDTO;
        if (obj.offeringType === OfferingType.subscription && obj.billingCycle === ValidBillingCycles.topUp) {
            return 'Subscription offerings cannot use topUp billing cycle';
        }
        if (obj.billingCycle === ValidBillingCycles.topUp) {
            return 'topUpAmount is required for topUp billing cycle';
        }
        return 'topUpAmount and topUpThreshold are only valid for topUp billing cycle';
    }
}

