async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<string | void> {
    if (this.billingCycle !== ValidBillingCycles.topUp || !this.topUpAmount) {
        return;
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    const topUpThreshold = parseFloat(this.topUpThreshold ?? '0.2');
    const thresholdBalance = topUpThreshold * topUpAmount;
    let currentBalance = 0;
    if (this.creditService) {
        const { balance } = await this.creditService.findCreditBalance(
            { businessID: this.businessID, customerId: customer.customerId },
            false,
        );
        currentBalance = parseFloat(balance);
    }
    if (currentBalance >= thresholdBalance) {
        return;
    }
    const unitCost = Math.round((topUpAmount - currentBalance) * 100) / 100;
    if (unitCost <= 0) {
        return;
    }
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, unitCost));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId: customer.customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

